#!/usr/bin/env python3
"""Verify installed node_modules against package-lock.json (read-only)."""
import json, os, sys

ROOT = "/opt/nxeon"
NM = os.path.join(ROOT, "node_modules")
LOCK = os.path.join(ROOT, "package-lock.json")

lock = json.load(open(LOCK))
lockpkgs = lock.get("packages", {})

# Walk node_modules tree collecting package dirs (handles @scope and nesting)
found = {}  # relpath (like "node_modules/foo") -> dict


def scan(nm_dir, rel_prefix):
    try:
        entries = sorted(os.listdir(nm_dir))
    except OSError as e:
        print("ERR listdir", nm_dir, e, file=sys.stderr)
        return
    for e in entries:
        if e in (".bin", ".package-lock.json", ".cache", ".modules.yaml"):
            continue
        p = os.path.join(nm_dir, e)
        if not os.path.isdir(p):
            continue
        if e.startswith("@"):
            try:
                subs = sorted(os.listdir(p))
            except OSError:
                continue
            for s in subs:
                sp = os.path.join(p, s)
                if os.path.isdir(sp):
                    record(sp, rel_prefix + "/" + e + "/" + s)
        else:
            record(p, rel_prefix + "/" + e)


def record(pkgdir, relpath):
    pj = os.path.join(pkgdir, "package.json")
    info = {"dir": pkgdir, "has_pj": os.path.isfile(pj),
            "islink": os.path.islink(pkgdir), "name": None, "version": None,
            "scripts": {}, "bin": None}
    if info["has_pj"]:
        try:
            d = json.load(open(pj, encoding="utf-8", errors="replace"))
            info["name"] = d.get("name")
            info["version"] = d.get("version")
            sc = d.get("scripts") or {}
            if isinstance(sc, dict):
                for k in ("preinstall", "install", "postinstall",
                          "preuninstall", "postuninstall", "prepare",
                          "prepublish", "prepack"):
                    if k in sc:
                        info["scripts"][k] = sc[k]
            info["bin"] = d.get("bin")
            info["gypfile"] = d.get("gypfile")
        except Exception as ex:
            info["error"] = str(ex)
    found[relpath] = info
    # recurse
    nested = os.path.join(pkgdir, "node_modules")
    if os.path.isdir(nested) and not os.path.islink(nested):
        scan(nested, relpath + "/node_modules")


scan(NM, "node_modules")

mismatch, missing_lock, missing_disk, nopj = [], [], [], []

for rel, info in sorted(found.items()):
    lk = lockpkgs.get(rel)
    if lk is None:
        missing_lock.append((rel, info))
        continue
    lv = lk.get("version")
    iv = info["version"]
    if lk.get("link"):
        continue
    if not info["has_pj"]:
        nopj.append((rel, info))
        continue
    if lv is not None and iv != lv:
        mismatch.append((rel, iv, lv))

for rel, lk in sorted(lockpkgs.items()):
    if rel == "" or not rel.startswith("node_modules"):
        continue
    if lk.get("link"):
        continue
    if rel not in found:
        missing_disk.append((rel, lk.get("version")))

print("=== COUNTS ===")
print("packages on disk:", len(found))
print("lock entries (node_modules/*):",
      len([k for k in lockpkgs if k.startswith("node_modules")]))
print()
print("=== VERSION MISMATCH (%d) ===" % len(mismatch))
for rel, iv, lv in mismatch:
    print("  %s : installed=%s locked=%s" % (rel, iv, lv))
print()
print("=== ON DISK, NOT IN LOCK (%d) ===" % len(missing_lock))
for rel, info in missing_lock:
    print("  %s : name=%s version=%s link=%s haspj=%s" %
          (rel, info["name"], info["version"], info["islink"], info["has_pj"]))
print()
print("=== IN LOCK, NOT ON DISK (%d) ===" % len(missing_disk))
for rel, v in missing_disk:
    print("  %s : locked=%s" % (rel, v))
print()
print("=== NO package.json ON DISK (%d) ===" % len(nopj))
for rel, info in nopj:
    print("  %s" % rel)
print()
print("=== NAME FIELD != DIRECTORY NAME ===")
for rel, info in sorted(found.items()):
    if not info["has_pj"]:
        continue
    dirname = rel.split("node_modules/")[-1]
    if info["name"] and info["name"] != dirname:
        print("  %s : package.json name=%s" % (rel, info["name"]))
print()
print("=== LIFECYCLE SCRIPTS ===")
n = 0
for rel, info in sorted(found.items()):
    if info["scripts"]:
        n += 1
        print("  %s @ %s  gypfile=%s" % (rel, info["version"], info.get("gypfile")))
        for k, v in info["scripts"].items():
            print("      %-16s %s" % (k, v))
print("total packages with lifecycle-ish scripts:", n)

# Dump JSON for later use
json.dump({k: {kk: vv for kk, vv in v.items()} for k, v in found.items()},
          open("/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/found.json", "w"), indent=1)

