#!/usr/bin/env python3
"""Download each locked tarball, verify sha512 integrity, and byte-compare
every installed file under /opt/nxeon/node_modules. STRICTLY READ-ONLY on
/opt/nxeon. Work dir is the scratchpad."""
import base64, hashlib, json, os, sys, tarfile, urllib.request, io
from concurrent.futures import ThreadPoolExecutor

ROOT = "/opt/nxeon"
NM = os.path.join(ROOT, "node_modules")
WORK = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad"
CACHE = os.path.join(WORK, "tarballs")
os.makedirs(CACHE, exist_ok=True)

lock = json.load(open(os.path.join(ROOT, "package-lock.json")))
pkgs = lock["packages"]

targets = []
for rel, meta in pkgs.items():
    if not rel.startswith("node_modules"):
        continue
    if meta.get("link"):
        continue
    disk = os.path.join(ROOT, rel)
    if not os.path.isdir(disk):
        continue  # optional platform dep not installed
    targets.append((rel, meta, disk))

print("packages to verify:", len(targets), flush=True)

results = []


def digest_bytes(b, alg):
    h = hashlib.new(alg)
    h.update(b)
    return h.digest()


def fetch(url, dest):
    if os.path.exists(dest) and os.path.getsize(dest) > 0:
        return open(dest, "rb").read()
    for attempt in range(3):
        try:
            req = urllib.request.Request(
                url, headers={"User-Agent": "ir-verify/1.0"})
            with urllib.request.urlopen(req, timeout=90) as r:
                data = r.read()
            tmp = dest + ".part"
            open(tmp, "wb").write(data)
            os.replace(tmp, dest)
            return data
        except Exception as e:
            if attempt == 2:
                raise
    return None


def norm(p):
    # strip leading "package/" from tar member names
    parts = p.split("/", 1)
    return parts[1] if len(parts) > 1 else None


def verify(item):
    rel, meta, disk = item
    out = {"rel": rel, "version": meta.get("version"), "status": "ok",
           "integrity_ok": None, "modified": [], "extra": [], "missing": [],
           "error": None}
    url = meta.get("resolved")
    integ = meta.get("integrity")
    safe = rel.replace("/", "_") + "-" + str(meta.get("version")) + ".tgz"
    dest = os.path.join(CACHE, safe)
    try:
        data = fetch(url, dest)
    except Exception as e:
        out["status"] = "download_failed"
        out["error"] = repr(e)[:200]
        return out

    # integrity check
    if integ:
        alg, b64 = integ.split("-", 1)
        want = base64.b64decode(b64)
        got = digest_bytes(data, alg)
        out["integrity_ok"] = (want == got)
        if not out["integrity_ok"]:
            out["status"] = "INTEGRITY_MISMATCH"
            return out

    # build map of tarball contents
    tar_files = {}
    try:
        with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as tf:
            for m in tf.getmembers():
                if not m.isfile():
                    continue
                n = norm(m.name)
                if n is None:
                    continue
                f = tf.extractfile(m)
                if f is None:
                    continue
                tar_files[n] = hashlib.sha256(f.read()).hexdigest()
    except Exception as e:
        out["status"] = "untar_failed"
        out["error"] = repr(e)[:200]
        return out

    # walk installed dir, skipping nested node_modules (own lock entries)
    disk_files = {}
    for r, dirs, files in os.walk(disk):
        if "node_modules" in dirs:
            dirs.remove("node_modules")
        for fn in files:
            p = os.path.join(r, fn)
            if os.path.islink(p):
                continue
            k = os.path.relpath(p, disk)
            try:
                with open(p, "rb") as fh:
                    disk_files[k] = hashlib.sha256(fh.read()).hexdigest()
            except OSError as e:
                disk_files[k] = "UNREADABLE:" + str(e)

    for k, h in disk_files.items():
        if k not in tar_files:
            out["extra"].append(k)
        elif tar_files[k] != h:
            out["modified"].append(k)
    for k in tar_files:
        if k not in disk_files:
            out["missing"].append(k)
    if out["modified"] or out["extra"]:
        out["status"] = "DIFF"
    return out


with ThreadPoolExecutor(max_workers=12) as ex:
    for i, r in enumerate(ex.map(verify, targets)):
        results.append(r)
        if (i + 1) % 50 == 0:
            print("  ...%d/%d" % (i + 1, len(targets)), flush=True)

json.dump(results, open(os.path.join(WORK, "tarball_results.json"), "w"),
          indent=1)

print()
print("=== SUMMARY ===")
from collections import Counter
print(Counter(r["status"] for r in results))
bad_int = [r for r in results if r["integrity_ok"] is False]
print("INTEGRITY MISMATCHES:", len(bad_int))
for r in bad_int:
    print("  !!!", r["rel"], r["version"])
print()
print("=== PACKAGES WITH MODIFIED FILES (content differs from official tarball) ===")
for r in sorted(results, key=lambda x: -len(x["modified"])):
    if r["modified"]:
        print("  %s @ %s : %d modified" % (r["rel"], r["version"], len(r["modified"])))
        for f in r["modified"][:15]:
            print("        M %s" % f)
print()
print("=== PACKAGES WITH EXTRA FILES (present on disk, not in official tarball) ===")
for r in sorted(results, key=lambda x: -len(x["extra"])):
    if r["extra"]:
        print("  %s @ %s : %d extra" % (r["rel"], r["version"], len(r["extra"])))
        for f in r["extra"][:15]:
            print("        + %s" % f)
print()
print("=== DOWNLOAD/UNTAR FAILURES ===")
for r in results:
    if r["status"] in ("download_failed", "untar_failed"):
        print("  %s : %s %s" % (r["rel"], r["status"], r["error"]))

